import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"火雷噬嗑","description":"周易折中 - 火雷噬嗑","frontmatter":{"title":"火雷噬嗑","description":"周易折中 - 火雷噬嗑"},"headers":[],"relativePath":"zh/classics/zhezhong/027.md","filePath":"zh/classics/zhezhong/027.md"}'),h={name:"zh/classics/zhezhong/027.md"};function p(n,a,d,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="火雷噬嗑" tabindex="-1">火雷噬嗑 <a class="header-anchor" href="#火雷噬嗑" aria-label="Permalink to “火雷噬嗑”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>噬嗑序卦:可观而后有所合，故受之以噬嗑。嗑者，合也。既有可观，然后有来合之者也。噬嗑所以次观也。噬，啮也；嗑，合也。口中有物闲之，啮而后合之也。卦上下二刚爻而中柔，外刚中虚，人颐口之象也。中虚之中又一刚爻，为颐中有物之象。口中有物则隔其上下，不得嗑，必啮之则得嗑，故为噬嗑。</p><p>圣人以卦之象推之于天下之事：在口则为有物隔而不得合，在天下则为有强梗或谗邪闲隔于其间，故天下之事不得合也。当用刑法，小则惩戒，大则诛戮，以除去之，然后天下之治得成矣。凡天下至于一国一家，至于万事，所以不和合者，皆由有闲也。无闲则合矣，以至天地之生，万物之成，皆合而后能遂。凡未合者，皆有闲也。</p><p>若君臣父子、亲戚朋友之间，有离贰怨隙者，盖谗邪闲于其间也。除去之则和合矣。故闲隔者，天下之大害也。圣人观噬嗑之象，推之于天下万事，皆使去其闲隔而合之，则无不和且洽矣。噬嗑者，治天下之大用也。去天下之闲，在任刑罚，故卦取用刑为义。在二体明照而威震，乃用刑之象也。</p><p>噬嗑：亨，利用狱</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>噬，啮也；嗑，合也。物有闲者，啮而合之也。为卦上下两阳而中虚，颐口之象。九四一阳闲于其中，必啮之而后合，故为噬嗑。其占当得亨通者，有闲故不通，啮之而合则亨通矣。又三阴三阳，刚柔中半，下动上明，下雷上电，本自益卦六四之柔上行以至于五而得其中，是知以阴居阳虽不当位，而利用狱。盖治狱之道，惟威与明而得其中之为贵，故筮得之者，有其德则应其占也。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>噬嗑亨，卦自有亨义也。天下之事所以不得亨者，以有闲也。噬而嗑之，则亨通矣。利用狱，噬而嗑之之道，宜用刑狱也。天下之闲，非刑狱何以去之？不云利用刑而云利用狱者，卦有明照之象，利于察狱也。狱者，所以究治情伪，得其情则知为闲之道，然后可以设防与致刑也。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li>李氏舜臣曰 ：噬嗑，震下离上，天地生物，有为造物之梗者，必用雷电击搏之。圣人治天下，有为民之梗者，必用刑狱断制之。故噬嗑以去颐中之梗，雷电以去天地之梗，刑狱以去天下之梗也。</li></ul><p>象曰：雷电噬嗑，先王以明罚敕法</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>雷电当作电雷。</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>象无倒置者，疑此文互也。雷电相须并见之物，亦有嗑象。电明而雷威，先王观雷电之象，法其明与威，以明其刑罚，饬其法令。法者，明事理而为之防者也。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>侯氏行果曰 ：雷所以动物，电所以照物。雷电震照，则万物不能懐邪。故先王则之，明罚敕法，以示万物也。</p></li><li><p>项氏安世曰 ：阴阳相噬而有声则为雷，有光则为电。二物因噬而嗑，故曰雷电噬嗑。</p></li><li><p>徐氏几曰 ：明罚者，所以示民而使之知所避；敕法者，所以防民而使之知所畏。此先王忠厚之意也。未至折狱致刑处，故与丰象异。</p></li><li><p>张氏清子曰 ：蔡邕石经本作电雷。</p></li><li><p>蔡氏清曰 ：先王以明罚敕法，此以立法言，故曰先王。若丰折狱致刑，以用法言，则曰君子矣。</p></li><li><p>薛氏瑄曰 ：噬嗑、贲、丰、旅四卦论用刑，皆离火之用。以是见用法贵乎明，噬嗑、丰以火雷、雷火交互为体，用法贵乎威明并济；贲、旅以山火、火山交互为体，用法贵乎明慎并用。</p></li></ul><p>彖曰：颐中有物曰噬嗑</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>以卦体释卦名义。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏宗传曰：《易》之立卦，其命名立象各有所指。鼎、井、大过（栋桡）、小过（飞鸟），若此类者，远取诸物也；艮背、颐（颐噬嗑）、颐中有物，若此类者，近取诸身也。</li></ul><p>噬嗑而亨，刚柔分动而明，雷电合而章，柔得中而上行，虽不当位，利用狱也</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>又以卦名、卦体、卦德、二象、卦变释卦辞。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>颐中有物，故为噬嗑。有物间于颐中，则为害；噬而嗑之，则其害亡，乃亨通也。故云“噬嗑而亨”。刚柔分动而明，雷电合而章，以卦才言也。刚爻与柔爻相闲，刚柔分而不相杂，为明辨之象，明辨察狱之本也。动而明，下震上离，其动而明也。雷电合而章，雷震而电耀，相须并见，合而章也。照与威并行，用狱之道也。能照则无所隐情，有威则莫敢不畏。上既以二象言其动而明，故复言威照并用之意。六五以柔居中为用，柔得中之义。上行谓居尊位，虽不当位，谓以柔居五为不当，而利于用狱者，治狱之道全刚则伤于严暴，过柔则失于宽纵。五为用狱之主，以柔处刚而得中，得用狱之宜也。以柔居刚为利用狱，以刚居柔为利否。曰刚柔质也，居用也，用柔非治狱之宜也。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>崔氏憬曰：物在颐中，隔其上下，因啮而合，乃得其亨焉。以喻人于上下之闲有乱群者，当用刑去之，故言“利用狱”。</p></li><li><p>石氏介曰：大凡柔则言上行，刚则言来。柔下刚上，定体也。刚来如讼、无妄、涣等，刚体本在上而来下；上行如晋、睽、鼎、噬嗑等，柔体本在下，今居五位为上行。</p></li><li><p>朱氏震曰：六五柔中不当位也，施于用狱无若柔中之为利。盖人君止于仁，不以明断称。以皋陶“宁失不经”，曾子“哀矜而勿喜”之言观之，则不在明断审矣。</p></li><li><p>赵氏汝梅曰：体卦之画则宽严胥济，体卦之德则明清善听，体卦之象则狱不淹宿。噬以刚动而能嗑，《彖》言“利用狱”，疑当以刚能断制，而圣人归之六五之柔，其哀矜惟良之义乎？大君在上，三宥而后制刑，德虽柔于狱，则利。</p></li><li><p>俞氏琰曰：噬嗑倒转为贲，亦有颐中有物之象，而以为贲何耶？曰：凡噬者必下动，贲无震，故不得为噬嗑也。夫颐而中虚，则无事于噬而自可合；今有物焉，则窒塞矣。苟不以齿决之，乌得而合？故噬已则嗑，嗑则窒者去而上下亨通。故文王曰“噬嗑亨”，孔子添一“而”字，盖谓噬而嗑之则亨，不噬则不嗑，不嗑则不亨也。</p></li></ul><p>初九：屦校灭趾，无咎</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>初上无位，为受刑之象。中四爻为用刑之象。初在卦始，罪薄过小，又在卦下，故为“屦校灭趾”之象。止恶于初，故得无咎。占者小伤而无咎也。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>九居初最下，无位者也，下民之象，为受刑之人。当用刑之始，罪小而刑轻。校，木械也。其过小，故屦之于足，以灭伤其趾。人有小过，校而灭其趾，则当惩惧，不敢进于恶矣，故得无咎。系辞云：“小惩而大诫”，此小人之福也。言惩之于小与初，故得无咎也。初与上无位，为受刑之人。馀四爻皆为用刑之人。初居最下无位者也，上处尊位之上，过于尊位亦无位者也。王弼以为无阴阳之位，阴阳系于奇偶，岂容无也？然诸卦初上不言当位不当位者，盖初终之义为大。临之初九则以位为正，若需上六云不当位，干上九云无位，爵位之位非阴阳之位也。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰 ：居无位之地以处刑，初受刑而非治刑者也。凡过之所始，必始于微而后至于著；罚之所始，必始于薄而后至于诛。过轻戮薄，故屦校灭趾，桎其行也，足惩而已，故不重也。过而不改，乃谓之过；小惩大诫，乃得其福，故无咎也。</p></li><li><p>俞氏琰曰 ：校，狱具也；初在下，趾象也；灭，没而不见也。以刚物加于著屦之足而没其趾，故曰“屦校灭趾”。惩之于小，戒之于初，则不进于恶，故无咎。</p></li><li><p>姜氏宝曰 ：灭，没也。言屦校于足而遮没其趾，非伤灭其趾之谓也。</p></li></ul><p>象曰：屦校灭趾，不行也</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>灭趾，又有不进于恶之象。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>屦校而灭伤其趾，则知惩诫而不敢长其恶，故云不行也。古人制刑，有小罪则校其趾，盖取禁止其行使，不进于恶也。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><p>胡氏炳文曰 ：下卦为震，灭趾使其不敢如震之动也，动则进于恶矣。</p><p>六二：噬肤灭鼻，无咎</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>祭有肤鼎，盖肉之柔脆，噬而易嗑者。六二中正，故其所治如噬肤之易然。以柔乘刚，故虽甚易亦不免于伤，灭其鼻。占者虽伤而终无咎也。</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>二应五之位，用刑者也。四爻皆取噬为义。二居中得正，是用刑得其中正也。用刑得其中正，则罪恶者易服，故取噬肤为象，噬啮人之肌肤为易入也。灭，没也，深入至没其鼻也。二以中正之道，其刑易服，然乘初刚，是用刑于刚强之人，刑刚强之人必须深痛，故至灭鼻而无咎也。中正之道易以服人与严刑以待刚强，义不相妨。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖达曰 ：六二处中得位，是用刑者。肤是柔脆之物，以喻服罪受刑之人也。乘刚而刑，未尽顺噬，过其分，故至灭鼻。言用刑太深也，刑中其理，故无咎。</p></li><li><p>胡氏炳文曰 ：噬而言肤、腊、胏、肉者，取颐中有物之象也。各爻虽取所噬之难易而言，然因各爻自有此象，故其所噬者因而为之象耳。六二柔而中正，故所治如噬肤之易入。初刚未服，不能无伤，然始虽有伤，终可服也。</p></li></ul><p>象曰：噬肤灭鼻，乘刚也</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>深至灭鼻者，乘刚故也。乘刚乃用刑于刚强之人，不得不深严也。深严则得宜，乃所谓中也。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><p>孔氏颖达曰 ：乘刚者，释噬肤灭鼻之义，以其乘刚故用刑深也。</p><p>六三：噬腊肉遇毒，小吝无咎</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>腊肉谓兽腊，全体骨而为之者，坚韧之物也。阴柔不中正，治人而人不服，为“噬腊肉遇毒”之象。占虽小吝，然时当噬嗑，于义为无咎也。</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>三居下之上，用刑者也。六居三处不当位，自处不得其当而刑于人，则人不服而怨怼悖犯之，如噬啮干腊（坚韧之物）而遇毒恶之味，反伤于口也。用刑而人不服，反致怨伤，是可鄙吝也。然当噬嗑之时，大要噬闲而嗑之，虽其身处位不当而强梗难服，至于遇毒，然用刑非为不当也，故虽可吝而亦小。噬而嗑之，非有咎也。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li>胡氏炳文曰 ：肉因六柔取象，腊因三刚取象。六二柔居柔，故所噬象肤之柔；六三柔居刚，故所噬象腊肉，柔中有刚，比之二难矣。二三皆无咎而三小吝者，中正不中正之分也。</li></ul><p>象曰：遇毒，位不当也</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>六三以阴居阳处，位不当，自处不当，故所刑者难服而反毒之也。</p><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>此亦借爻位之不当以明其所处之难尔，非其所行有不当也。若所行有不当，则施之刑狱，其失大矣，安得无咎，又岂独小吝而已乎？</p><p>九四：噬干胏，得金矢，利艰贞吉</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>胏，肉之带骨者，与胾通。《周礼》狱讼入钧金束矢而后听之。九四以刚居柔，得用刑之道，故有此象。言所噬愈坚而得听讼之宜也。然必利于艰难正固，则吉。戒占者宜如是也。</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>九四居近君之位，当噬嗑之任者也。四已过中，是其间愈大而用刑愈深也。故云噬干胏。胏，肉之有聮骨者，干肉而兼骨，至坚难噬者也。噬至坚而得金矢，金取刚，矢取直。九四阳德刚直，为得刚直之道。虽用刚直之道，利在克艰其事而贞固其守则吉也。九四刚而明，体阳而居柔，刚明则伤于果，故戒以知难；居柔则守不固，故戒以坚贞。刚而不贞者有矣，凡失刚者皆不贞也。在噬嗑，四最为善。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>陆氏绩曰 ：金矢者，刚直也。噬胏虽难，终得申其刚直也。</p></li><li><p>杨氏时曰 ：九四合一卦言之，则为间者；以爻言，则居近君之位，任除闲之责者也。易之取象不同类如此。</p></li><li><p>王氏宗传曰 ：以一卦言之，则九四颐中之物也，所以为强梗者也；以六爻言之，则九四刚直之才也，所以去强梗者也。肉之附骨者谓之胏，而又干焉，亦最难噬者也。然三之于腊肉，则遇毒；而四之于干胏，则无是患者，刚柔之才异也。</p></li><li><p>丘氏富国曰 ：噬嗑惟四五两爻能尽治狱之道。彖以五之柔为主，故曰“柔得中而上行，虽不当位，利用狱也”。利用之言独归之五，而他爻不与焉。爻以四之刚为主，故曰“噬干胏得金矢，利艰贞吉”。吉之言独归之四，而他爻谓之无咎也。主柔而言，以仁为治狱之本；主刚而言，以威为治狱之用。仁以寓其哀矜，威以惩其奸慝。刚柔迭用，畏爱兼施，治狱之道得矣。</p></li><li><p>胡氏炳文曰 ：离为乾卦，故为干胏（腊肉）。肉藏骨，柔中有刚。六三柔居刚，故所噬如之（干胏）。骨连肉，刚中有柔。九四刚居柔，故所噬如之三（腊肉）。遇毒所治之人不服也，四得金矢，其人服矣。然必艰难正固，乃无咎。</p></li></ul><p>象曰：利艰贞吉，未光也</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>凡言未光，其道未光大也。戒于利艰贞，盖其所不足也，不得中正故也。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><p>方氏应祥曰 ：虑听讼者之心有所未光，故以利艰贞为戒。</p><p>六五：噬干肉，得黄金，贞厉无咎</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>噬干肉，难于肤而易于腊胏者也。黄，中色；金，亦谓钧金。六五柔顺而中，以居尊位，用刑于人，人无不服，故有此象。然必贞厉乃得无咎，亦戒占者之辞也。</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>五在卦愈上而为噬干肉，反易于四之干胏者，五居尊位，乘在上之势以刑于下，其势易也。在卦将极矣，其为间甚大，非易嗑也，故为噬干肉也。得黄金，黄中色，金刚物。五居中为得中道，处刚而四辅以刚，得黄金也。五无应而四居大臣之位，得其助也。贞厉无咎，六五虽处中刚，然实柔体，故戒以必正固而怀危厉，则得无咎也。以柔居尊而当噬嗑之时，岂可不贞固而怀危惧哉？</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱子语类问 ：九四“利艰贞”，六五“贞厉”，皆有艰难正固、危惧之意，故皆为戒占者之辞。曰：“亦是爻中元自有此道理。大抵才是治人，彼必为敌，不是易事。故虽是时位卦德得用刑之宜，亦须以艰难正固处之。”</p></li><li><p>李氏过曰 ：九四以刚噬，六五以柔噬。以刚噬者，有司执法之公；以柔噬者，人君不忍之仁也。</p></li><li><p>胡氏炳文曰 ：噬肤、噬腊肉、噬干胏，一节难于一节。六五噬干肉则易矣。五君位也，以柔居刚，柔而得中，用狱之道也，何难之有？讼则出矢，狱则出金。讼为小，狱为大。四于讼狱兼得，大小兼理之也。五君也，非大狱不敢以闻。《书》所谓“罔攸兼于庶狱”是也。</p></li><li><p>谷氏家杰曰 ：四先艰而后贞者，先以艰难存心，而后出入罔不得其正。此狱未成之前详审之法，人臣以执法为道也。五先贞而后厉者，虽出入无不得正，而犹以危厉惕其心。此狱既成之后钦恤之仁，人君以好生为德也。</p></li></ul><p>象曰：贞厉无咎，得当也</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>所以能无咎者，以所为得其当也。所谓当，居中用刚而能守正虑危也。</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><p>赵氏汝梅曰 ：释彖言不当位，此言得当者，释彖以位言，此以事言。六五以柔用狱，行以正厉，其无咎者，得用狱之当者也。 林氏希元曰 ：得当即是得用刑之道，不就爻位说。若果是说位得中当，以解得黄金不宜，以解贞厉无咎矣。</p><p>上九：何校灭耳，凶</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>何，负也。过极之阳在卦之上，恶极罪大，凶之道也。故其象占如此。</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>上，过乎尊位，无位者也，故为受刑者。居卦之终，是其闲太噬之极也。《系辞》所谓“恶积而不可揜，罪大而不可解”者也。故何校而灭其耳，凶可知矣。何，负也，谓在颈也。</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li>郭氏雍曰 ：初上“灭”字，或以为刑。独孔氏训“没”，屦校桎其足，桎大而灭趾；何校械其首，械大而没耳也。或以灭耳为刵（割耳），灭鼻为劓（割鼻），灭趾为剕（断足）。《书注》劓、刵轻刑，《吕刑》剕辟为重，故汉斩趾同于弃市。方初九小刑，固不当断趾；上九罪大，复不当轻刑。以是知三者言“灭”，皆非刑也。</li></ul><p>象曰：何校灭耳，聪不明也</p><h3 id="本义-11" tabindex="-1">本义 <a class="header-anchor" href="#本义-11" aria-label="Permalink to “本义”">​</a></h3><p>灭耳，盖罪其听之不聪也。若能审听而早图之，则无此凶矣。</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>人之聋暗不悟，积其罪恶以至于极。古人制法，罪之大者何之以校，为其无所闻知，积成其恶，故以校而灭伤其耳，诫聪之不明也。</p><h3 id="集说-14" tabindex="-1">集说 <a class="header-anchor" href="#集说-14" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>胡氏炳文曰 ：上卦为离，灭耳言其不能如离之明也。</p></li><li><p>林氏希元曰 ：聪字单言则包明与，明并言则聪又为体而明为用。</p></li></ul><p>总论</p><ul><li>李氏过曰 ：以六爻之位言之，五君位也，为治狱之主；四大臣位也，为治狱之卿；三二又其下也，为治狱之吏。上九则已处卦之极，过乎大臣之位，故为受刑者。其象占显示其恶极罪大，终受重刑，凶之至也。</li></ul>',109)])])}const m=e(h,[["render",p]]);export{b as __pageData,m as default};
